import React from 'react';
import styled from '@emotion/styled';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';

const HeroSection = styled.section`
  min-height: 60vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: linear-gradient(135deg, ${props => props.theme.colors.primary} 0%, #6c5ce7 100%);
  position: relative;
  overflow: hidden;
  padding: 4rem 2rem;
  text-align: center;
`;

const HeroTitle = styled(motion.h1)`
  font-size: 3.5rem;
  color: white;
  margin-bottom: 1.5rem;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.2);
`;

const HeroSubtitle = styled(motion.p)`
  font-size: 1.5rem;
  color: white;
  margin-bottom: 2rem;
  max-width: 600px;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 1rem;
  margin-top: 2rem;
`;

const Button = styled(motion(Link))`
  padding: 1rem 2rem;
  font-size: 1.2rem;
  background: white;
  color: ${props => props.theme.colors.primary};
  border: none;
  border-radius: 30px;
  cursor: pointer;
  text-decoration: none;
  transition: transform 0.3s ease;
  
  &:hover {
    transform: scale(1.05);
  }
`;

const SecondaryButton = styled(Button)`
  background: transparent;
  border: 2px solid white;
  color: white;
  
  &:hover {
    background: white;
    color: ${props => props.theme.colors.primary};
  }
`;

const Hero: React.FC = () => {
  return (
    <HeroSection>
      <HeroTitle
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
      >
        Transform Your Body with Calisthenics
      </HeroTitle>
      <HeroSubtitle
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, delay: 0.2 }}
      >
        Build strength, flexibility, and endurance using only your body weight. No equipment needed!
      </HeroSubtitle>
      <ButtonGroup>
        <Button
          to="/benefits"
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.95 }}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.4 }}
        >
          Learn More
        </Button>
        <SecondaryButton
          to="/benefits"
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.95 }}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.5 }}
        >
          View Benefits
        </SecondaryButton>
      </ButtonGroup>
    </HeroSection>
  );
};

export default Hero;
